def solve(**kwargs):
    import time
    import math

    start_time = time.time()
    deadline = start_time + 8.5

    n = int(kwargs.get("num_planes", 0))
    r = int(kwargs.get("num_runways", 1))
    planes = kwargs.get("planes", [])
    sep = kwargs.get("separation", [])

    if n == 0:
        return {"schedule": {}}

    E = [float(p["earliest"]) for p in planes]
    T = [float(p["target"]) for p in planes]
    L = [float(p["latest"]) for p in planes]
    PE = [float(p["penalty_early"]) for p in planes]
    PL = [float(p["penalty_late"]) for p in planes]

    def separation(i, j):
        try:
            return float(sep[i][j])
        except Exception:
            return 0.0

    def plane_cost(i, t):
        if t <= T[i]:
            return (T[i] - t) * PE[i]
        return (t - T[i]) * PL[i]

    def optimize_sequence(seq, do_refine=True):
        m = len(seq)
        if m == 0:
            return [], 0.0
        lb = [0.0] * m
        ub = [0.0] * m

        for k, p in enumerate(seq):
            if k == 0:
                lb[k] = E[p]
            else:
                lb[k] = max(E[p], lb[k - 1] + separation(seq[k - 1], p))

        for k in range(m - 1, -1, -1):
            p = seq[k]
            if k == m - 1:
                ub[k] = L[p]
            else:
                ub[k] = min(L[p], ub[k + 1] - separation(p, seq[k + 1]))

        for k in range(m):
            if lb[k] > ub[k] + 1e-7:
                return None, float("inf")

        times = [0.0] * m
        for k, p in enumerate(seq):
            x = T[p]
            if x < lb[k]:
                x = lb[k]
            elif x > ub[k]:
                x = ub[k]
            times[k] = x

        # Enforce feasibility.
        for k in range(1, m):
            need = times[k - 1] + separation(seq[k - 1], seq[k])
            if times[k] < need:
                times[k] = need
        for k in range(m - 2, -1, -1):
            lim = times[k + 1] - separation(seq[k], seq[k + 1])
            if times[k] > lim:
                times[k] = lim
        for k in range(m):
            if times[k] < E[seq[k]] - 1e-7 or times[k] > L[seq[k]] + 1e-7:
                return None, float("inf")

        if do_refine:
            passes = 5 if m <= 80 else 3
            for _ in range(passes):
                changed = False
                for k, p in enumerate(seq):
                    lo = E[p]
                    hi = L[p]
                    if k > 0:
                        lo = max(lo, times[k - 1] + separation(seq[k - 1], p))
                    if k + 1 < m:
                        hi = min(hi, times[k + 1] - separation(p, seq[k + 1]))
                    old = times[k]
                    x = T[p]
                    if x < lo:
                        x = lo
                    elif x > hi:
                        x = hi
                    times[k] = x
                    if abs(old - x) > 1e-9:
                        changed = True
                if not changed:
                    break

        cost = 0.0
        for k, p in enumerate(seq):
            t = times[k]
            if t < E[p] - 1e-6 or t > L[p] + 1e-6:
                return None, float("inf")
            if k > 0 and t + 1e-6 < times[k - 1] + separation(seq[k - 1], p):
                return None, float("inf")
            cost += plane_cost(p, t)
        return times, cost

    def build(order):
        seqs = [[] for _ in range(r)]
        seq_costs = [0.0] * r
        total = 0.0

        for idx, p in enumerate(order):
            if time.time() > deadline:
                return None, float("inf"), None

            best = None
            best_delta = float("inf")
            best_cost = float("inf")

            # To keep very large instances fast, restrict insertion positions somewhat.
            for rw in range(r):
                seq = seqs[rw]
                m = len(seq)

                if n <= 120:
                    positions = range(m + 1)
                else:
                    # Candidate positions near target order plus ends.
                    pos = 0
                    while pos < m and T[seq[pos]] <= T[p]:
                        pos += 1
                    cand = {0, m, pos}
                    if pos > 0:
                        cand.add(pos - 1)
                    if pos < m:
                        cand.add(pos + 1)
                    positions = sorted(x for x in cand if 0 <= x <= m)

                for pos in positions:
                    newseq = seq[:pos] + [p] + seq[pos:]
                    times, c = optimize_sequence(newseq, do_refine=(n <= 160))
                    if times is None:
                        continue
                    delta = c - seq_costs[rw]
                    # slight load balancing tie-break
                    score = delta + 1e-7 * len(seq)
                    if score < best_delta:
                        best_delta = score
                        best = (rw, pos, newseq, times)
                        best_cost = c

            if best is None:
                return None, float("inf"), None

            rw, pos, newseq, times = best
            total += best_cost - seq_costs[rw]
            seqs[rw] = newseq
            seq_costs[rw] = best_cost

        all_times = {}
        final_cost = 0.0
        for rw in range(r):
            times, c = optimize_sequence(seqs[rw], do_refine=True)
            if times is None:
                return None, float("inf"), None
            final_cost += c
            for k, p in enumerate(seqs[rw]):
                all_times[p] = (times[k], rw + 1)

        return seqs, final_cost, all_times

    indices = list(range(n))

    def slack(i):
        return L[i] - E[i]

    orders = []
    orders.append(sorted(indices, key=lambda i: (T[i], L[i], E[i])))
    orders.append(sorted(indices, key=lambda i: (L[i], T[i], E[i])))
    orders.append(sorted(indices, key=lambda i: (slack(i), T[i])))
    orders.append(sorted(indices, key=lambda i: (E[i], T[i], L[i])))

    # If many runways, targets are often feasible with one plane per runway.
    if r >= n:
        schedule = {}
        for i in range(n):
            schedule[i + 1] = {"landing_time": float(min(max(T[i], E[i]), L[i])), "runway": i + 1}
        return {"schedule": schedule}

    best_cost = float("inf")
    best_times = None

    seen = set()
    for order in orders:
        key = tuple(order)
        if key in seen:
            continue
        seen.add(key)
        if time.time() > deadline:
            break
        seqs, cost, times_map = build(order)
        if times_map is not None and cost < best_cost:
            best_cost = cost
            best_times = times_map

    if best_times is None:
        # Last-resort greedy append construction.
        seqs = [[] for _ in range(r)]
        cur = [-1e100] * r
        cur_plane = [None] * r
        for p in sorted(indices, key=lambda i: T[i]):
            best_rw = 0
            best_t = float("inf")
            for rw in range(r):
                t = max(E[p], T[p])
                if cur_plane[rw] is not None:
                    t = max(t, cur[rw] + separation(cur_plane[rw], p))
                if t <= L[p] + 1e-7 and t < best_t:
                    best_t = t
                    best_rw = rw
            if best_t == float("inf"):
                best_rw = min(range(r), key=lambda x: cur[x])
                best_t = max(E[p], min(L[p], T[p]))
                if cur_plane[best_rw] is not None:
                    best_t = max(best_t, cur[best_rw] + separation(cur_plane[best_rw], p))
                    best_t = min(best_t, L[p])
            seqs[best_rw].append(p)
            cur[best_rw] = best_t
            cur_plane[best_rw] = p

        best_times = {}
        for rw in range(r):
            times, c = optimize_sequence(seqs[rw], do_refine=True)
            if times is None:
                tprev = None
                pprev = None
                for p in seqs[rw]:
                    t = min(max(T[p], E[p]), L[p])
                    if pprev is not None:
                        t = max(t, tprev + separation(pprev, p))
                        t = min(t, L[p])
                    best_times[p] = (float(t), rw + 1)
                    tprev, pprev = t, p
            else:
                for k, p in enumerate(seqs[rw]):
                    best_times[p] = (float(times[k]), rw + 1)

    schedule = {}
    for i in range(n):
        if i in best_times:
            t, rw = best_times[i]
        else:
            t, rw = min(max(T[i], E[i]), L[i]), 1
        schedule[i + 1] = {"landing_time": float(t), "runway": int(rw)}

    return {"schedule": schedule}
