def solve(**kwargs):
    import time
    import random

    start_time = time.time()
    deadline = start_time + 8.7

    n = int(kwargs["num_planes"])
    m = max(1, int(kwargs["num_runways"]))
    planes = kwargs["planes"]
    sep = kwargs["separation"]

    E = [float(p["earliest"]) for p in planes]
    T = [float(p["target"]) for p in planes]
    L = [float(p["latest"]) for p in planes]
    PE = [float(p["penalty_early"]) for p in planes]
    PL = [float(p["penalty_late"]) for p in planes]

    def penalty(i, t):
        if t < T[i]:
            return (T[i] - t) * PE[i]
        return (t - T[i]) * PL[i]

    def time_sequence(seq, passes=4):
        """Return feasible landing times for a fixed runway sequence, or None."""
        k = len(seq)
        if k == 0:
            return [], 0.0

        times = [0.0] * k

        # Earliest feasible schedule for this sequence.
        prev_t = None
        prev_i = None
        for pos, i in enumerate(seq):
            if pos == 0:
                t = E[i]
            else:
                t = max(E[i], prev_t + float(sep[prev_i][i]))
            if t > L[i] + 1e-9:
                return None
            times[pos] = t
            prev_t = t
            prev_i = i

        # Coordinate improvement: move each plane as close to target as possible
        # while respecting fixed neighbours.
        for _ in range(passes):
            changed = False

            for pos in range(k - 1, -1, -1):
                i = seq[pos]
                lb = E[i]
                ub = L[i]
                if pos > 0:
                    j = seq[pos - 1]
                    lb = max(lb, times[pos - 1] + float(sep[j][i]))
                if pos + 1 < k:
                    j = seq[pos + 1]
                    ub = min(ub, times[pos + 1] - float(sep[i][j]))
                if lb > ub + 1e-9:
                    return None
                nt = min(max(T[i], lb), ub)
                if abs(nt - times[pos]) > 1e-9:
                    times[pos] = nt
                    changed = True

            for pos in range(k):
                i = seq[pos]
                lb = E[i]
                ub = L[i]
                if pos > 0:
                    j = seq[pos - 1]
                    lb = max(lb, times[pos - 1] + float(sep[j][i]))
                if pos + 1 < k:
                    j = seq[pos + 1]
                    ub = min(ub, times[pos + 1] - float(sep[i][j]))
                if lb > ub + 1e-9:
                    return None
                nt = min(max(T[i], lb), ub)
                if abs(nt - times[pos]) > 1e-9:
                    times[pos] = nt
                    changed = True

            if not changed:
                break

        c = 0.0
        for pos, i in enumerate(seq):
            if times[pos] < E[i] - 1e-7 or times[pos] > L[i] + 1e-7:
                return None
            if pos > 0:
                j = seq[pos - 1]
                if times[pos] < times[pos - 1] + float(sep[j][i]) - 1e-7:
                    return None
            c += penalty(i, times[pos])
        return times, c

    def evaluate(runways):
        all_times = [None] * n
        total = 0.0
        for rseq in runways:
            res = time_sequence(rseq)
            if res is None:
                return None
            ts, c = res
            total += c
            for pos, i in enumerate(rseq):
                all_times[i] = ts[pos]
        for i in range(n):
            if all_times[i] is None:
                return None
        return total, all_times

    def greedy_build(order, mode=0):
        runways = [[] for _ in range(m)]

        for i in order:
            best = None

            for r in range(m):
                base = runways[r]

                # Usually append. For smaller instances also try all insertion positions.
                if n <= 70:
                    positions = range(len(base) + 1)
                else:
                    positions = (len(base),)

                for pos in positions:
                    cand_seq = base[:pos] + [i] + base[pos:]
                    res = time_sequence(cand_seq, passes=2)
                    if res is None:
                        continue

                    old_res = time_sequence(base, passes=2)
                    old_cost = old_res[1] if old_res is not None else 0.0
                    inc = res[1] - old_cost

                    # Tie breakers differ by mode.
                    last_time = res[0][-1] if res[0] else 0.0
                    load = len(base)
                    if mode == 0:
                        key = (inc, last_time, load)
                    elif mode == 1:
                        key = (last_time, inc, load)
                    else:
                        key = (load, inc, last_time)

                    if best is None or key < best[0]:
                        best = (key, r, pos)

            if best is None:
                return None

            _, r, pos = best
            runways[r] = runways[r][:pos] + [i] + runways[r][pos:]

        ev = evaluate(runways)
        if ev is None:
            return None
        return runways, ev[0], ev[1]

    def copy_runways(rw):
        return [x[:] for x in rw]

    # Candidate construction orders.
    idx = list(range(n))
    orders = []
    orders.append(sorted(idx, key=lambda i: (T[i], L[i], E[i])))
    orders.append(sorted(idx, key=lambda i: (L[i], T[i], E[i])))
    orders.append(sorted(idx, key=lambda i: (E[i], T[i], L[i])))
    orders.append(sorted(idx, key=lambda i: (L[i] - E[i], L[i], T[i])))
    orders.append(sorted(idx, key=lambda i: (T[i] - E[i], T[i])))
    orders.append(sorted(idx, key=lambda i: (L[i] - T[i], L[i])))

    best_runways = None
    best_times = None
    best_cost = float("inf")

    for order in orders:
        if time.time() > deadline:
            break
        for mode in range(3):
            if time.time() > deadline:
                break
            sol = greedy_build(order, mode)
            if sol is not None:
                rw, c, ts = sol
                if c < best_cost:
                    best_cost = c
                    best_runways = rw
                    best_times = ts

    # Randomized greedy attempts.
    rng = random.Random(12345 + n * 17 + m)
    attempts = 0
    while time.time() < deadline and attempts < 80:
        attempts += 1
        order = sorted(
            idx,
            key=lambda i: (
                T[i] + rng.uniform(-0.25, 0.25) * max(1.0, L[i] - E[i]),
                L[i],
            ),
        )
        sol = greedy_build(order, attempts % 3)
        if sol is not None:
            rw, c, ts = sol
            if c < best_cost:
                best_cost = c
                best_runways = rw
                best_times = ts

    # Local search around best solution.
    if best_runways is not None:
        no_improve = 0
        while time.time() < deadline and no_improve < 500:
            improved = False
            cur = copy_runways(best_runways)

            op = rng.randrange(3)
            if op == 0:
                # Move one plane to another runway/position.
                nonempty = [r for r in range(m) if cur[r]]
                if nonempty:
                    r1 = rng.choice(nonempty)
                    p1 = rng.randrange(len(cur[r1]))
                    plane = cur[r1].pop(p1)
                    r2 = rng.randrange(m)
                    pos = rng.randrange(len(cur[r2]) + 1)
                    cur[r2].insert(pos, plane)
            elif op == 1:
                # Swap two planes.
                nonempty = [r for r in range(m) if cur[r]]
                if len(nonempty) >= 1:
                    r1 = rng.choice(nonempty)
                    r2 = rng.choice(nonempty)
                    p1 = rng.randrange(len(cur[r1]))
                    p2 = rng.randrange(len(cur[r2]))
                    cur[r1][p1], cur[r2][p2] = cur[r2][p2], cur[r1][p1]
            else:
                # Reverse a small segment on one runway.
                nonempty = [r for r in range(m) if len(cur[r]) >= 2]
                if nonempty:
                    r = rng.choice(nonempty)
                    a = rng.randrange(len(cur[r]) - 1)
                    b = rng.randrange(a + 1, len(cur[r]))
                    if b - a <= 8:
                        cur[r][a:b + 1] = reversed(cur[r][a:b + 1])

            ev = evaluate(cur)
            if ev is not None and ev[0] + 1e-9 < best_cost:
                best_cost, best_times = ev
                best_runways = cur
                improved = True

            if improved:
                no_improve = 0
            else:
                no_improve += 1

    # If no feasible sequence was found, return a conservative fallback.
    # This may be infeasible on hard instances, but avoids crashing.
    if best_times is None:
        schedule = {}
        for i, p in enumerate(planes, start=1):
            schedule[i] = {
                "landing_time": float(min(max(p["target"], p["earliest"]), p["latest"])),
                "runway": ((i - 1) % m) + 1,
            }
        return {"schedule": schedule}

    plane_runway = [1] * n
    for r, seq in enumerate(best_runways, start=1):
        for i in seq:
            plane_runway[i] = r

    schedule = {}
    for i in range(n):
        schedule[i + 1] = {
            "landing_time": float(best_times[i]),
            "runway": int(plane_runway[i]),
        }

    return {"schedule": schedule}
