def solve(**kwargs):
    import time
    import math
    import random

    start_time = time.time()
    deadline = start_time + 8.8

    C = kwargs.get("bin_capacity")
    items = list(kwargs.get("items", []))
    n = kwargs.get("num_items", len(items))

    if n == 0:
        return {"num_bins": 0, "bins": []}

    indexed = [(items[i], i + 1) for i in range(n)]

    def pack_best_fit(order):
        bins = []
        rems = []
        for size, idx in order:
            best = -1
            best_rem = C + 1
            for b, r in enumerate(rems):
                if r >= size:
                    nr = r - size
                    if nr < best_rem:
                        best_rem = nr
                        best = b
            if best == -1:
                bins.append([idx])
                rems.append(C - size)
            else:
                bins[best].append(idx)
                rems[best] -= size
        return bins, rems

    def pack_first_fit(order):
        bins = []
        rems = []
        for size, idx in order:
            placed = False
            for b in range(len(bins)):
                if rems[b] >= size:
                    bins[b].append(idx)
                    rems[b] -= size
                    placed = True
                    break
            if not placed:
                bins.append([idx])
                rems.append(C - size)
        return bins, rems

    def normalize_bins(bins):
        return [b for b in bins if b]

    def compute_rems(bins):
        return [C - sum(items[i - 1] for i in b) for b in bins]

    def try_eliminate(bins):
        bins = [list(b) for b in bins]
        improved = True
        while improved and time.time() < deadline:
            improved = False
            rems = compute_rems(bins)
            loads = [C - r for r in rems]
            order_bins = sorted(range(len(bins)), key=lambda x: loads[x])
            for bi in order_bins:
                if time.time() >= deadline:
                    break
                if bi >= len(bins) or not bins[bi]:
                    continue
                moving = sorted(bins[bi], key=lambda x: items[x - 1], reverse=True)
                tmp_bins = [list(b) for k, b in enumerate(bins) if k != bi]
                tmp_rems = [r for k, r in enumerate(rems) if k != bi]
                ok = True
                for idx in moving:
                    s = items[idx - 1]
                    best = -1
                    best_rem = C + 1
                    for j, r in enumerate(tmp_rems):
                        if r >= s and r - s < best_rem:
                            best_rem = r - s
                            best = j
                    if best == -1:
                        ok = False
                        break
                    tmp_bins[best].append(idx)
                    tmp_rems[best] -= s
                if ok:
                    bins = tmp_bins
                    improved = True
                    break
        return normalize_bins(bins)

    desc = sorted(indexed, key=lambda x: (-x[0], x[1]))
    asc = sorted(indexed, key=lambda x: (x[0], x[1]))

    candidates = []
    b, _ = pack_best_fit(desc)
    candidates.append(b)
    b, _ = pack_first_fit(desc)
    candidates.append(b)
    b, _ = pack_best_fit(asc)
    candidates.append(b)

    best_bins = min(candidates, key=len)
    best_bins = try_eliminate(best_bins)

    total = sum(items)
    lower_bound = max((total + C - 1) // C, max(items) <= C and 1 or 0)

    rng = random.Random(1234567 + n + total)
    attempts = 0
    while len(best_bins) > lower_bound and time.time() < deadline and attempts < 80:
        attempts += 1
        if n > 2500 and attempts > 8:
            break
        if n > 800 and attempts > 20:
            break

        if attempts % 3 == 0:
            order = desc[:]
            i = 0
            while i < n:
                j = i + 1
                while j < n and order[j][0] == order[i][0]:
                    j += 1
                if j - i > 1:
                    part = order[i:j]
                    rng.shuffle(part)
                    order[i:j] = part
                i = j
        else:
            order = desc[:]
            block = max(2, min(30, n // 10 + 1))
            for i in range(0, n, block):
                part = order[i:i + block]
                rng.shuffle(part)
                order[i:i + block] = part

        b, _ = pack_best_fit(order)
        if len(b) <= len(best_bins):
            b = try_eliminate(b)
            if len(b) < len(best_bins):
                best_bins = b

    def exact_pack(k):
        if k < lower_bound or time.time() >= deadline:
            return None

        order = sorted(indexed, key=lambda x: (-x[0], x[1]))
        sizes = [x[0] for x in order]
        ids = [x[1] for x in order]

        rem = [C] * k
        bins = [[] for _ in range(k)]

        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + sizes[i]

        nodes = [0]
        node_limit = 250000
        if n <= 45:
            node_limit = 1200000
        elif n <= 80:
            node_limit = 600000

        def dfs(pos):
            nodes[0] += 1
            if (nodes[0] & 4095) == 0:
                if nodes[0] > node_limit or time.time() >= deadline:
                    return False

            if pos == n:
                return True

            if sum(rem) < suffix[pos]:
                return False

            s = sizes[pos]
            idx = ids[pos]

            tried_rems = set()
            choices = []
            for b in range(k):
                if rem[b] >= s:
                    choices.append((rem[b] - s, b))
            choices.sort()

            for _, b in choices:
                r = rem[b]
                if r in tried_rems:
                    continue
                tried_rems.add(r)

                rem[b] -= s
                bins[b].append(idx)

                if dfs(pos + 1):
                    return True

                bins[b].pop()
                rem[b] += s

                if r == C:
                    break
                if r == s:
                    break

            return False

        if dfs(0):
            return [list(b) for b in bins if b]
        return None

    if n <= 180 and len(best_bins) > lower_bound and time.time() < deadline:
        while len(best_bins) > lower_bound and time.time() < deadline:
            target = len(best_bins) - 1
            res = exact_pack(target)
            if res is None:
                break
            best_bins = res

    best_bins = normalize_bins(best_bins)

    return {
        "num_bins": len(best_bins),
        "bins": best_bins
    }
